--
-- Table structure for table `orders`
--

DROP TABLE IF EXISTS `orders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `orders` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `supplier_id` int(11) NOT NULL DEFAULT 0,
  `medicine_id` int(11) NOT NULL,
  `quantity` int(11) NOT NULL,
  `unit_price` decimal(10,2) NOT NULL,
  `total_cost` decimal(10,2) GENERATED ALWAYS AS (`quantity` * `unit_price`) STORED,
  `status` varchar(50) NOT NULL DEFAULT 'pending',
  `order_date` datetime DEFAULT current_timestamp(),
  `expected_delivery` date DEFAULT NULL,
  `actual_delivery` date DEFAULT NULL,
  `delivered_at` datetime DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `notes` text DEFAULT NULL,
  `payment_method` varchar(50) NOT NULL DEFAULT 'cash',
  `payment_reference` varchar(100) DEFAULT NULL,
  `delivery_status` varchar(50) DEFAULT NULL,
  `delivery_updated_at` datetime DEFAULT NULL,
  `ordered_by` int(11) DEFAULT NULL,
  `user_id` int(11) DEFAULT NULL,
  `total_amount` decimal(10,2) NOT NULL DEFAULT 0.00,
  `accepted_date` datetime DEFAULT NULL,
  `paid_date` datetime DEFAULT NULL,
  `fulfilled_date` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `supplier_id` (`supplier_id`),
  KEY `medicine_id` (`medicine_id`),
  KEY `user_id` (`user_id`),
  KEY `fk_orders_ordered_by` (`ordered_by`),
  KEY `idx_orders_status` (`status`),
  KEY `idx_orders_supplier` (`supplier_id`),
  KEY `idx_orders_date` (`order_date`),
  KEY `idx_supplier_status` (`supplier_id`,`status`),
  KEY `idx_order_date` (`order_date`),
  KEY `idx_accepted_date` (`accepted_date`),
  KEY `idx_paid_date` (`paid_date`),
  KEY `idx_orders_supplier_status` (`supplier_id`,`status`),
  KEY `idx_supplier_id` (`supplier_id`),
  KEY `idx_medicine_id` (`medicine_id`),
  KEY `idx_status` (`status`),
  KEY `idx_orders_status_delivery` (`status`,`delivery_status`),
  CONSTRAINT `fk_orders_medicine` FOREIGN KEY (`medicine_id`) REFERENCES `medicines` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_orders_ordered_by` FOREIGN KEY (`ordered_by`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_orders_supplier` FOREIGN KEY (`supplier_id`) REFERENCES `suppliers` (`id`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=196 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

