--
-- Table structure for table `purchases`
--

DROP TABLE IF EXISTS `purchases`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `purchases` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `medicine_id` int(11) DEFAULT NULL,
  `pharmacist_id` int(11) DEFAULT NULL,
  `purchase_number` varchar(50) NOT NULL,
  `status` enum('pending','filled','cancelled') DEFAULT 'pending',
  `notes` text DEFAULT NULL,
  `total_cost` decimal(10,2) DEFAULT 0.00,
  `filled_by_user_id` int(11) DEFAULT NULL,
  `purchase_date` date DEFAULT NULL,
  `quantity` int(11) DEFAULT NULL,
  `payment_method` enum('cash','credit_card','debit_card','insurance','gcash','maya') DEFAULT 'cash',
  `payment_status` enum('paid','partial','pending','refunded') DEFAULT 'pending',
  `amount_paid` decimal(10,2) DEFAULT 0.00,
  `change_given` decimal(10,2) DEFAULT 0.00,
  `updated_at` timestamp NULL DEFAULT NULL ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `purchase_number` (`purchase_number`),
  KEY `medicine_id` (`medicine_id`),
  KEY `pharmacist_id` (`pharmacist_id`),
  KEY `filled_by_user_id` (`filled_by_user_id`),
  KEY `idx_status` (`status`),
  KEY `idx_purchase_status` (`status`),
  CONSTRAINT `fk_purchases_medicine` FOREIGN KEY (`medicine_id`) REFERENCES `medicines` (`id`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=43 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

